/**
 * "Prevent all combat damage that would be dealt this turn." and its relatives: a prevention effect
 * generated by a resolving spell or ability (CR 615), a shield that lasts "this turn" (CR 514.2: it
 * ends at cleanup). Two rules, because they have different recipients:
 *
 * - `effect.prevent-all`: all damage, all combat damage or all noncombat damage, to everything
 *   (nothing named), to one or more recipients ("to you", "to creatures you control", "to and dealt
 *   by target creature") or only from one source ("dealt by target creature"). One shield prevents
 *   everything, so a list of recipients is one shield per recipient (CR 615.1).
 * - `effect.prevent-next`: "the next N damage" to ONE recipient (CR 615.7), or to each of a group
 *   of untargeted creatures, where it is a shield for each (CR 615.11). A list of recipients and a
 *   plural without "each" ("creatures you control") are not read with a number: CR 615.7 does not
 *   say whether the number is shared, and 615.11 covers "each of a number of untargeted creatures".
 *
 * Not read, each stopping where the text goes beyond the shield: "can't be prevented" (CR 615.12),
 * a source of the player's choice and "the next time a source would deal damage" (CR 609.7a, 615.8),
 * "instead" (a replacement effect, CR 614), a duration other than "this turn", and a source that is
 * not one object ("creatures you control", "sources you control": the engine's `by` is one
 * reference, never a filter).
 */
import {
  choice,
  fail,
  literal,
  map,
  optional,
  type Parser,
  pattern,
  quiet,
  satisfy,
  separatedBy1,
  sequence,
} from '../../combinators';
import type {
  IrAmount,
  IrArg,
  IrDamageScope,
  IrDuration,
  IrNoun,
  IrNounList,
  Span,
} from '../../ir/types';
import { defineRule, family, spanned } from '../registry';
import { type Clauses, LIST_SEPARATOR, single } from './operands';

const ALL = 'effect.prevent-all';
const NEXT = 'effect.prevent-next';

type Scope = IrDamageScope['scope'];

/** "damage", "combat damage" or "noncombat damage" (CR 120.2a: combat damage is dealt in combat). */
const DAMAGE_WORDS: Parser<Scope> = map(
  pattern(/(noncombat |combat )?damage(?![\p{L}\p{N}])/iu),
  (m): Scope => {
    const word = (m[1] ?? '').trim().toLowerCase();
    return word === 'combat' || word === 'noncombat' ? word : 'all';
  },
);

/**
 * The parser's value when `accept` says yes. Otherwise the parse fails where the phrase began and
 * leaves no other trace, so the diagnostic points at the refused words ("two target creatures") and
 * not at what the noun rule happened to try after them.
 */
function strict<T>(parser: Parser<T>, accept: (value: T) => boolean): Parser<T> {
  const checked = quiet(satisfy(parser, accept));
  return (ctx, pos) => {
    const r = checked(ctx, pos);
    return r.ok ? r : fail(ctx, pos);
  };
}

/** A recipient that is one object, one player or a group checked as damage is dealt (not "two target ..."). */
const isOne = (noun: IrNoun): boolean => !(noun.det === 'target' && noun.plural);

/** Recipients of "all damage": who or what the shield protects. */
const ALL_RECIPIENTS = [
  // Stage P47 (D-202): "to ~", the permanent that has the ability (the planeswalker that becomes a creature, "Prevent all damage that would be dealt to him this turn").
  'noun.self',
  'noun.player',
  'noun.any-target',
  'noun.target-permanent',
  'noun.each-permanent',
  'noun.plain-permanents',
] as const;

/** Recipients of "the next N damage": one player, one target, or each of a group of creatures. */
const NEXT_RECIPIENTS = [
  'noun.player',
  'noun.any-target',
  'noun.target-permanent',
  'noun.each-permanent',
] as const;

/**
 * The one recipient of a numeric shield: a player, a target, or each of a group of creatures
 * (CR 615.11), never "each player" and never a list.
 */
const NEXT_ONE: Parser<IrNoun> = strict(
  family<IrNoun>('noun', { only: NEXT_RECIPIENTS }),
  (noun) => isOne(noun) && noun.det !== 'eachPlayer' && noun.det !== 'eachOpponent',
);

/** The source of "dealt by target creature": one target, never a group (CR 609.7a). */
const SOURCE: Parser<IrNoun> = strict(
  family<IrNoun>('noun', { only: ['noun.target-permanent'] }),
  (noun) => !noun.plural,
);

/** One or more recipients of "all damage": "you", "you and creatures you control" (each is a shield). */
const ALL_TO: Parser<IrNoun | IrNounList> = map(
  spanned(
    separatedBy1(strict(family<IrNoun>('noun', { only: ALL_RECIPIENTS }), isOne), LIST_SEPARATOR),
  ),
  ({ value: items, span }): IrNoun | IrNounList => {
    const [first] = items;
    return items.length === 1 && first !== undefined
      ? first
      : { kind: 'nounList', items, span, rule: ALL };
  },
);

/** What follows "that would be dealt": the recipients and the source, as the text names them. */
interface Tail {
  readonly to?: IrNoun | IrNounList;
  readonly by?: IrNoun;
  /** "by non-Spider creatures" (stage P32): a group of sources, as each damage event would happen. */
  readonly byFilter?: IrNoun;
}

/**
 * The sources of "dealt by non-Spider creatures", "dealt by creatures you don't control" (stage P32, D-147, CR 615.1, 609.7): a plural
 * group of permanents, never one object, read as each damage event would happen. The words are those of a permanent phrase (a type, a
 * creature type, "non-Spider", a controller).
 */
const SOURCE_FILTER: Parser<IrNoun> = strict(
  family<IrNoun>('noun', { only: ['noun.plain-permanents'] }),
  (noun) => noun.plural && noun.filter.anyOf === undefined,
);

/**
 * " to him", " to her" (stage P47, D-202): the pronoun of a legendary card for itself ("Until end of turn, ~ becomes a 6/6 ... creature that's still a
 * planeswalker. Prevent all damage that would be dealt to him this turn."). It names the permanent that has the ability, as `~` does.
 */
const SELF_PRONOUN: Parser<IrNoun> = map(
  spanned(pattern(/ to (?:him|her)(?![\p{L}\p{N}])/iu)),
  ({ span }): IrNoun => ({
    kind: 'noun',
    det: 'self',
    filter: { raw: 'him' },
    upTo: false,
    plural: false,
    other: false,
    span,
    rule: ALL,
  }),
);

const TAIL: Parser<Tail> = (ctx, pos) => {
  // "to him": the permanent itself, said with a pronoun.
  const himself = SELF_PRONOUN(ctx, pos);
  if (himself.ok) return { ok: true, value: { to: himself.value }, pos: himself.pos };
  // "to and dealt by X" first: it starts like "to X".
  const both = sequence(literal(' to and dealt by '), SOURCE)(ctx, pos);
  if (both.ok) return { ok: true, value: { to: both.value[1], by: both.value[1] }, pos: both.pos };
  const to = sequence(literal(' to '), ALL_TO)(ctx, pos);
  if (to.ok) return { ok: true, value: { to: to.value[1] }, pos: to.pos };
  const by = sequence(literal(' by '), SOURCE)(ctx, pos);
  if (by.ok) return { ok: true, value: { by: by.value[1] }, pos: by.pos };
  const group = quiet(sequence(literal(' by '), SOURCE_FILTER))(ctx, pos);
  if (group.ok) return { ok: true, value: { byFilter: group.value[1] }, pos: group.pos };
  return { ok: true, value: {}, pos };
};

/** " for as long as ~ remains on the battlefield" (stage P50, D-207, CR 611.2b): the shield of an ability of a permanent, which ends as it leaves. */
function whileSelfRemains(rule: string): Parser<IrDuration> {
  return map(
    spanned(literal(' for as long as ~ remains on the battlefield')),
    ({ span }): IrDuration => ({ kind: 'duration', scope: 'whileSelfRemains', span, rule }),
  );
}

/** " this turn": the shield lasts until the cleanup step (CR 514.2). */
function thisTurn(rule: string): Parser<IrDuration> {
  return map(
    spanned(literal(' this turn')),
    ({ span }): IrDuration => ({ kind: 'duration', scope: 'thisTurn', span, rule }),
  );
}

function scopeNode(
  rule: string,
  span: Span,
  scope: Scope,
  amount: IrDamageScope['amount'],
): IrDamageScope {
  return { kind: 'damageScope', scope, amount, span, rule };
}

/**
 * `effect.prevent-all`: "Prevent all combat damage that would be dealt this turn.", "... to you
 * this turn", "... to you and creatures you control this turn", "... to and dealt by target
 * creature this turn", "... dealt by target creature this turn" (CR 615.1, 615.6). When the text
 * names a recipient and a source with "to and dealt by", `to` and `by` are the same noun and mean
 * two shields: damage dealt to it, and damage dealt by it.
 */
export const EFFECT_PREVENT_ALL = defineRule<Clauses>({
  id: ALL,
  family: 'effect',
  leading: ['prevent'],
  cites: [
    'CR 615.1 (Prevention Effects)',
    'CR 615.6 (Prevention Effects)',
    'CR 609.7a (Damage)',
    'CR 120.3 (Damage)',
    'CR 514.2 (Cleanup Step)',
  ],
  examples: [
    'prevent all combat damage that would be dealt this turn',
    'prevent all damage that would be dealt this turn',
    'prevent all noncombat damage that would be dealt this turn',
    'prevent all damage that would be dealt to you this turn',
    'prevent all combat damage that would be dealt to you this turn',
    'prevent all damage that would be dealt to creatures you control this turn',
    'prevent all damage that would be dealt to each creature you control this turn',
    'prevent all damage that would be dealt to you and creatures you control this turn',
    'prevent all damage that would be dealt to target player this turn',
    'prevent all damage that would be dealt to target creature this turn',
    'prevent all damage that would be dealt to any target this turn',
    'prevent all damage that would be dealt to each opponent this turn',
    'prevent all combat damage that would be dealt to and dealt by target creature this turn',
    'prevent all combat damage that would be dealt by target creature this turn',
    // Stage P32 (D-147): the sources are a group.
    'prevent all combat damage that would be dealt this turn by non-Spider creatures',
    "prevent all damage that would be dealt this turn by creatures you don't control",
    'prevent all damage that would be dealt by creatures you control this turn',
    "prevent all combat damage that would be dealt by creatures you don't control this turn",
    'prevent all combat damage that would be dealt by Dragons this turn',
    // Stage P50 (D-207): for as long as the permanent with the ability remains on the battlefield.
    'prevent all damage that would be dealt by up to one target creature for as long as ~ remains on the battlefield',
    'prevent all damage that would be dealt by target creature for as long as ~ remains on the battlefield',
  ],
  rejects: [
    'prevent all combat damage that would be dealt',
    'prevent all combat damage that would be dealt this turn instead',
    'prevent all combat damage that would be dealt until end of turn',
    'prevent all combat damage that would be dealt until your next turn',
    'prevent all damage that would be dealt to you this turn by a source of your choice',
    'prevent all damage that would be dealt by sources you control this turn',
    'prevent all damage that would be dealt by creatures or sources this turn',
    'prevent all damage that would be dealt by creatures or planeswalkers this turn',
    'prevent all combat damage that would be dealt to two target creatures this turn',
    'prevent all combat damage that would be dealt by two target creatures this turn',
    'prevent all damage that would be dealt to target creature or player this turn',
    'prevent all combat damage that would be dealt to and dealt by that creature this turn',
    'prevent all combat damage that would be dealt to target creature and dealt by it this turn',
    'prevent all combat damage dealt this turn',
    'prevent the next 3 damage that would be dealt to you this turn',
    'prevent all damage that would be dealt to you and creatures you control this turn and draw a card',
    'prevent all damage that would be dealt by target creature for as long as you control ~',
    'prevent all damage that would be dealt by target creature for as long as ~ remains',
  ],
  parse: single(
    ALL,
    sequence(
      spanned(sequence(literal('prevent all '), DAMAGE_WORDS)),
      literal(' that would be dealt'),
      TAIL,
      choice(thisTurn(ALL), whileSelfRemains(ALL)),
      // "... would be dealt this turn by non-Spider creatures" (stage P32): the group of sources after the duration.
      optional(
        map(quiet(sequence(literal(' by '), SOURCE_FILTER)), ([, group]) => group),
        null,
      ),
    ),
    ([head, , tail, duration, after]) => {
      const byFilter = tail.byFilter ?? after ?? undefined;
      const args: Record<string, IrArg> = {
        scope: scopeNode(ALL, head.span, head.value[1], 'all'),
        ...(tail.to === undefined ? {} : { to: tail.to }),
        ...(tail.by === undefined ? {} : { by: tail.by }),
        ...(byFilter === undefined ? {} : { byFilter }),
      };
      return { verb: 'preventDamage', args, duration };
    },
  ),
});

/** The number of "the next N damage": a positive whole number (CR 615.7). */
const AMOUNT: Parser<IrAmount> = satisfy(
  family<IrAmount>('amount', { only: ['amount.number'] }),
  (amount) => amount.kind === 'number' && amount.value >= 1,
);

/**
 * `effect.prevent-next`: "Prevent the next 3 damage that would be dealt to any target this turn.",
 * "... to target creature this turn", "... to you this turn", "Prevent the next 2 combat damage that
 * would be dealt to you this turn", "Prevent the next 1 damage that would be dealt to each creature
 * you control this turn" (CR 615.7: a shield that is reduced by what it prevents; CR 615.11: one
 * for each creature). The recipient is always named, and there is one.
 */
export const EFFECT_PREVENT_NEXT = defineRule<Clauses>({
  id: NEXT,
  family: 'effect',
  leading: ['prevent'],
  cites: [
    'CR 615.7 (Prevention Effects)',
    'CR 615.11 (Prevention Effects)',
    'CR 120.3 (Damage)',
    'CR 514.2 (Cleanup Step)',
  ],
  examples: [
    'prevent the next 3 damage that would be dealt to any target this turn',
    'prevent the next three damage that would be dealt to any target this turn',
    'prevent the next 1 damage that would be dealt to target creature this turn',
    'prevent the next 2 damage that would be dealt to target player this turn',
    'prevent the next 5 damage that would be dealt to you this turn',
    'prevent the next 2 combat damage that would be dealt to you this turn',
    'prevent the next 4 noncombat damage that would be dealt to you this turn',
    'prevent the next 1 damage that would be dealt to each creature you control this turn',
  ],
  rejects: [
    'prevent the next 3 damage that would be dealt this turn',
    'prevent the next X damage that would be dealt to you this turn',
    'prevent the next 0 damage that would be dealt to you this turn',
    'prevent the next damage that would be dealt to you this turn',
    'prevent the next 1 damage that would be dealt to you and creatures you control this turn',
    'prevent the next 1 damage that would be dealt to creatures you control this turn',
    'prevent the next 1 damage that would be dealt to each player this turn',
    'prevent the next 1 damage that would be dealt to each opponent this turn',
    'prevent the next 2 damage that would be dealt by target creature this turn',
    'prevent the next 2 damage that would be dealt to two target creatures this turn',
    'prevent the next 3 damage that would be dealt to any target until end of turn',
    'prevent all damage that would be dealt to you this turn',
  ],
  parse: single(
    NEXT,
    sequence(
      spanned(sequence(literal('prevent the next '), AMOUNT, literal(' '), DAMAGE_WORDS)),
      literal(' that would be dealt'),
      literal(' to '),
      NEXT_ONE,
      thisTurn(NEXT),
    ),
    ([head, , , to, duration]) => {
      const [, amount, , scope] = head.value;
      const number = amount.kind === 'number' ? amount.value : 0;
      return {
        verb: 'preventDamage',
        args: { scope: scopeNode(NEXT, head.span, scope, number), to },
        duration,
      };
    },
  ),
});

export const PREVENT_RULES = [EFFECT_PREVENT_ALL, EFFECT_PREVENT_NEXT];
